/**
 * Yaffs2 object type enum.  The java enum ordinal must match the yaffs enum values.
 */
public class YAFFS2ObjectType
{	public static readonly YAFFS2ObjectType Unknown = new();
	public static readonly YAFFS2ObjectType File = new();
	public static readonly YAFFS2ObjectType Symlink = new();
	public static readonly YAFFS2ObjectType Directory = new();
	public static readonly YAFFS2ObjectType Hardlink = new();
	public static readonly YAFFS2ObjectType Special = new();
	public static readonly YAFFS2ObjectType INVALID = new();
        // represents value that doesn't match, including Unknown

	public static YAFFS2ObjectType parse(long i) {
		YAFFS2ObjectType[] values = values();
		return i > Unknown.ordinal() && i < INVALID.ordinal() ? values[(int) i] : INVALID;
	}
}
